//! Generates the decoding tables of `turbo-encoding` and the label table
//! of `turbo-encoding-layers` from the index files and `encodings.json` of
//! the WHATWG Encoding Standard.
//!
//! The downloads are not committed; the generated files are. To run it
//! again, fetch the files named in `analysis/encoding/README.md` into one
//! directory and run
//!
//! ```text
//! cargo run -p turbo-encoding-gen -- <download directory> <repository root>
//! ```
//!
//! The output depends only on the input files: every table is written in
//! pointer order and every file carries the identifier and date of the
//! index it came from.

use std::fmt::Write as _;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

/// The single-byte indexes, by file stem, with the name of the static each
/// becomes.
const SINGLE_BYTE: [(&str, &str); 27] = [
    ("ibm866", "IBM866"),
    ("iso-8859-2", "ISO_8859_2"),
    ("iso-8859-3", "ISO_8859_3"),
    ("iso-8859-4", "ISO_8859_4"),
    ("iso-8859-5", "ISO_8859_5"),
    ("iso-8859-6", "ISO_8859_6"),
    ("iso-8859-7", "ISO_8859_7"),
    ("iso-8859-8", "ISO_8859_8"),
    ("iso-8859-10", "ISO_8859_10"),
    ("iso-8859-13", "ISO_8859_13"),
    ("iso-8859-14", "ISO_8859_14"),
    ("iso-8859-15", "ISO_8859_15"),
    ("iso-8859-16", "ISO_8859_16"),
    ("koi8-r", "KOI8_R"),
    ("koi8-u", "KOI8_U"),
    ("macintosh", "MACINTOSH"),
    ("windows-874", "WINDOWS_874"),
    ("windows-1250", "WINDOWS_1250"),
    ("windows-1251", "WINDOWS_1251"),
    ("windows-1252", "WINDOWS_1252"),
    ("windows-1253", "WINDOWS_1253"),
    ("windows-1254", "WINDOWS_1254"),
    ("windows-1255", "WINDOWS_1255"),
    ("windows-1256", "WINDOWS_1256"),
    ("windows-1257", "WINDOWS_1257"),
    ("windows-1258", "WINDOWS_1258"),
    ("x-mac-cyrillic", "X_MAC_CYRILLIC"),
];

/// One index file: its header fields and its (pointer, code point) rows.
struct Index {
    name: String,
    identifier: String,
    date: String,
    rows: Vec<(u32, u32)>,
}

fn read_index(dir: &Path, stem: &str) -> Index {
    let name = format!("index-{stem}.txt");
    let path = dir.join(&name);
    let text = fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    let (mut identifier, mut date, mut rows) = (String::new(), String::new(), Vec::new());
    for (n, line) in text.lines().enumerate() {
        if let Some(comment) = line.strip_prefix('#') {
            let comment = comment.trim();
            if let Some(v) = comment.strip_prefix("Identifier:") {
                identifier = v.trim().to_string();
            } else if let Some(v) = comment.strip_prefix("Date:") {
                date = v.trim().to_string();
            }
            continue;
        }
        let mut fields = line.split_whitespace();
        let (Some(pointer), Some(code_point)) = (fields.next(), fields.next()) else { continue };
        let pointer: u32 = pointer.parse().unwrap_or_else(|_| panic!("{name}:{}: bad pointer", n + 1));
        let hex = code_point.strip_prefix("0x").unwrap_or_else(|| panic!("{name}:{}: bad code point", n + 1));
        let code_point = u32::from_str_radix(hex, 16).unwrap_or_else(|_| panic!("{name}:{}: bad code point", n + 1));
        rows.push((pointer, code_point));
    }
    assert!(!identifier.is_empty() && !date.is_empty(), "{name}: no identifier or date");
    assert!(rows.windows(2).all(|w| w[0].0 < w[1].0), "{name}: pointers out of order");
    Index { name, identifier, date, rows }
}

/// A generated Rust file.
struct Out {
    text: String,
}

impl Out {
    fn new(about: &str, sources: &[&Index]) -> Out {
        let mut text = String::new();
        let names: Vec<String> =
            sources.iter().map(|i| format!("{} (identifier {}, {})", i.name, i.identifier, i.date)).collect();
        for line in wrap(&format!(
            "Generated by turbo-encoding-gen from {} of the WHATWG Encoding Standard. Do not edit this file by hand: \
             change the generator and run it again as analysis/encoding/README.md describes. The index data is \
             used under the BSD 3-Clause licence; see NOTICE in this directory.",
            names.join(", ")
        )) {
            writeln!(text, "// {line}").unwrap();
        }
        writeln!(text, "//").unwrap();
        for line in wrap(about) {
            writeln!(text, "// {line}").unwrap();
        }
        Out { text }
    }

    /// A static array, sixteen values to a line, outside rustfmt's reach so
    /// the layout stays the generator's.
    fn array(&mut self, doc: &str, name: &str, ty: &str, values: &[u32]) {
        writeln!(self.text).unwrap();
        for line in wrap(doc) {
            writeln!(self.text, "/// {line}").unwrap();
        }
        writeln!(self.text, "#[rustfmt::skip]").unwrap();
        writeln!(self.text, "pub(crate) static {name}: [{ty}; {}] = [", values.len()).unwrap();
        for chunk in values.chunks(16) {
            let items: Vec<String> = chunk.iter().map(|v| format!("0x{v:04X}")).collect();
            writeln!(self.text, "    {},", items.join(", ")).unwrap();
        }
        writeln!(self.text, "];").unwrap();
    }

    fn constant(&mut self, doc: &str, name: &str, ty: &str, value: &str) {
        writeln!(self.text).unwrap();
        for line in wrap(doc) {
            writeln!(self.text, "/// {line}").unwrap();
        }
        writeln!(self.text, "pub(crate) const {name}: {ty} = {value};").unwrap();
    }
}

fn wrap(text: &str) -> Vec<String> {
    let mut lines = Vec::new();
    let mut line = String::new();
    for word in text.split_whitespace() {
        if !line.is_empty() && line.len() + 1 + word.len() > 76 {
            lines.push(std::mem::take(&mut line));
        }
        if !line.is_empty() {
            line.push(' ');
        }
        line.push_str(word);
    }
    if !line.is_empty() {
        lines.push(line);
    }
    lines
}

/// A dense table from pointer `first` to the last pointer, 0 where the index
/// has no code point (no index maps a pointer to U+0000).
fn dense(index: &Index, first: u32) -> Vec<u32> {
    let last = index.rows.last().expect("rows").0;
    let mut table = vec![0u32; (last - first + 1) as usize];
    for &(p, cp) in &index.rows {
        assert!(cp != 0, "{}: pointer {p} maps to U+0000", index.name);
        table[(p - first) as usize] = cp;
    }
    table
}

fn single_byte(dir: &Path) -> String {
    let indexes: Vec<(Index, &str)> = SINGLE_BYTE.iter().map(|&(stem, name)| (read_index(dir, stem), name)).collect();
    let refs: Vec<&Index> = indexes.iter().map(|(i, _)| i).collect();
    let mut out = Out::new(
        "The single-byte indexes: entry b is the code point of byte 0x80 + b, 0 where the byte has none.",
        &refs,
    );
    for (index, name) in &indexes {
        let mut table = vec![0u32; 128];
        for &(p, cp) in &index.rows {
            table[p as usize] = cp;
        }
        out.array(&format!("{}.", index.name), name, "u16", &table);
    }
    out.text
}

fn two_byte(dir: &Path, stem: &str, name: &str, about: &str, ty: &str) -> String {
    let index = read_index(dir, stem);
    let first = index.rows[0].0;
    let mut out = Out::new(about, &[&index]);
    out.constant(&format!("The first pointer {name} holds."), &format!("{name}_FIRST"), "usize", &first.to_string());
    let table = dense(&index, first);
    if ty == "u16" {
        assert!(table.iter().all(|&cp| cp <= 0xFFFF), "{}: a code point past the BMP", index.name);
    }
    out.array(&format!("{}, from pointer {first}; 0 where the index has no code point.", index.name), name, ty, &table);
    out.text
}

fn gb18030(dir: &Path) -> String {
    let index = read_index(dir, "gb18030");
    let ranges = read_index(dir, "gb18030-ranges");
    let mut out = Out::new(
        "The two-byte gb18030 index (every pointer has a code point) and the ranges of the four-byte sequences: \
         pointer i of the ranges table starts at code point i of the code point table.",
        &[&index, &ranges],
    );
    assert_eq!(index.rows.len(), 23940);
    out.array("index-gb18030.txt.", "GB18030", "u16", &dense(&index, 0));
    let pointers: Vec<u32> = ranges.rows.iter().map(|r| r.0).collect();
    let code_points: Vec<u32> = ranges.rows.iter().map(|r| r.1).collect();
    out.array("The pointers that start a range, ascending.", "GB18030_RANGE_POINTERS", "u32", &pointers);
    out.array("The code point each range starts at.", "GB18030_RANGE_CODE_POINTS", "u32", &code_points);
    out.text
}

/// The variant of `Encoding` for a WHATWG encoding name.
fn variant(name: &str) -> String {
    match name {
        "UTF-8" => "Utf8".into(),
        "ISO-8859-8-I" => "Iso8859_8I".into(),
        "Shift_JIS" => "ShiftJis".into(),
        "gb18030" => "Gb18030".into(),
        "GBK" => "Gbk".into(),
        "Big5" => "Big5".into(),
        "EUC-JP" => "EucJp".into(),
        "EUC-KR" => "EucKr".into(),
        "ISO-2022-JP" => "Iso2022Jp".into(),
        "UTF-16BE" => "Utf16Be".into(),
        "UTF-16LE" => "Utf16Le".into(),
        "IBM866" => "Ibm866".into(),
        "KOI8-R" => "Koi8R".into(),
        "KOI8-U" => "Koi8U".into(),
        "macintosh" => "Macintosh".into(),
        "replacement" => "Replacement".into(),
        "x-mac-cyrillic" => "XMacCyrillic".into(),
        "x-user-defined" => "XUserDefined".into(),
        _ => {
            if let Some(rest) = name.strip_prefix("ISO-8859-") {
                format!("Iso8859_{rest}")
            } else if let Some(rest) = name.strip_prefix("windows-") {
                format!("Windows{rest}")
            } else {
                panic!("no Encoding variant for {name}")
            }
        }
    }
}

/// The (label, name) pairs of `encodings.json`. The file is a fixed shape
/// (objects with `"labels": [...]` before `"name": "..."`), read without a
/// JSON library.
fn labels(dir: &Path) -> Vec<(String, String)> {
    let path = dir.join("encodings.json");
    let text = fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    let mut pairs = Vec::new();
    let mut pending: Vec<String> = Vec::new();
    let mut in_labels = false;
    for line in text.lines() {
        let line = line.trim();
        if line.starts_with("\"labels\"") {
            in_labels = true;
            pending.clear();
        } else if in_labels && line.starts_with(']') {
            in_labels = false;
        } else if in_labels {
            pending.push(line.trim_end_matches(',').trim_matches('"').to_string());
        } else if let Some(rest) = line.strip_prefix("\"name\": ") {
            let name = rest.trim_end_matches(',').trim_matches('"').to_string();
            for label in pending.drain(..) {
                pairs.push((label, name.clone()));
            }
        }
    }
    pairs.sort();
    assert!(pairs.windows(2).all(|w| w[0].0 != w[1].0), "a label named twice");
    pairs
}

fn labels_file(dir: &Path) -> String {
    let pairs = labels(dir);
    let mut text = String::new();
    for line in wrap(
        "Generated by turbo-encoding-gen from encodings.json of the WHATWG Encoding Standard. Do not edit this \
         file by hand: change the generator and run it again as analysis/encoding/README.md describes. The data \
         is used under the BSD 3-Clause licence; see analysis/encoding/src/tables/NOTICE.",
    ) {
        writeln!(text, "// {line}").unwrap();
    }
    writeln!(text, "\nuse crate::Encoding;\n").unwrap();
    writeln!(text, "/// Every label of the Encoding Standard, lowercase and sorted, with its encoding.").unwrap();
    writeln!(text, "#[rustfmt::skip]").unwrap();
    writeln!(text, "pub(crate) static LABELS: [(&str, Encoding); {}] = [", pairs.len()).unwrap();
    for (label, name) in &pairs {
        writeln!(text, "    ({label:?}, Encoding::{}),", variant(name)).unwrap();
    }
    writeln!(text, "];").unwrap();
    text
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 3 {
        eprintln!("usage: turbo-encoding-gen <download directory> <repository root>");
        return ExitCode::from(2);
    }
    let (dir, root) = (Path::new(&args[1]), PathBuf::from(&args[2]));
    let tables = root.join("analysis/encoding/src/tables");
    let files = [
        (tables.join("single_byte.rs"), single_byte(dir)),
        (
            tables.join("jis0208.rs"),
            two_byte(dir, "jis0208", "JIS0208", "JIS X 0208 with its extensions, for Shift_JIS and EUC-JP.", "u16"),
        ),
        (tables.join("jis0212.rs"), two_byte(dir, "jis0212", "JIS0212", "JIS X 0212, for EUC-JP.", "u16")),
        (tables.join("euc_kr.rs"), two_byte(dir, "euc-kr", "EUC_KR", "The euc-kr index (code page 949).", "u16")),
        (
            tables.join("big5.rs"),
            two_byte(
                dir,
                "big5",
                "BIG5",
                "The Big5 index with the HKSCS extensions; some code points are past the BMP.",
                "u32",
            ),
        ),
        (tables.join("gb18030.rs"), gb18030(dir)),
        (root.join("analysis/encoding-layers/src/labels.rs"), labels_file(dir)),
    ];
    for (path, text) in files {
        if let Err(e) = fs::write(&path, &text) {
            eprintln!("turbo-encoding-gen: cannot write {}: {e}", path.display());
            return ExitCode::FAILURE;
        }
        println!("{} ({} bytes)", path.display(), text.len());
    }
    ExitCode::SUCCESS
}
